INSERT INTO `admins` (`id`, `name`, `email`, `password_hash`, `role`) VALUES
  (1, 'AASTRA Administrator', 'admin@aastra.uk', '$2y$10$fgQl/XP/SGHg3Ho2MPQthuoyQYGFQDrXXvhbxdjB9fyp0G6m.l2Uy', 'admin')
INSERT INTO `categories` (`id`, `name`, `slug`, `section_label`, `side_tab_label`, `chapter_number`, `description`, `image_url`, `sort_order`, `is_active`) VALUES
  (1, 'Door Handles on Rose', 'door-handles-on-rose', 'HANDLES', 'DOOR HARDWARE', 1, 'Architectural lever handles mounted on concealed-fix round and square roses, engineered in SS304 and solid brass for commercial and luxury residential doors.', '/samples/arh201_photo.png', 1, 1),
  (2, 'Door Handles on Backplate', 'door-handles-on-backplate', 'HANDLES', 'DOOR HARDWARE', 2, 'Classic and contemporary lever handles on latch, lock, euro-profile, and bathroom backplates.', '/samples/arh202_photo.png', 2, 1),
  (3, 'Pull Handles', 'pull-handles', 'HANDLES', 'DOOR HARDWARE', 4, 'Heavy-duty tubular, mitred, and back-to-back architectural entrance pull handles for timber, aluminium, and glass doors.', '/samples/arh204_photo.png', 3, 1),
  (4, 'Flush Pulls', 'flush-pulls', 'HANDLES', 'DOOR HARDWARE', 5, 'Concealed-fixing circular, square, and rectangular recessed flush pulls in SS304 grade stainless steel for sliding and pocket doors.', '/samples/arh201_photo.png', 4, 1),
  (5, 'Door Hinges & Pivots', 'door-hinges', 'HINGES', 'DOOR HARDWARE', 6, 'Grade 13 ball-bearing butt hinges, 3D concealed hinges, and heavy-duty architectural pivots.', '/samples/aae683_photo.png', 5, 1),
  (6, 'Door Locks & Latches', 'door-locks-latches', 'LOCKS', 'DOOR HARDWARE', 7, 'CE-certified architectural mortice sashlocks, deadlocks, tubular latches, and euro cylinders.', '/samples/aae825_photo.png', 6, 1),
  (7, 'Door Stops', 'door-stops', 'ACCESSORIES', 'DOOR HARDWARE', 8, 'Floor-mounted half-dome, cove, magnetic, and wall-mounted architectural door stops crafted from SS304 stainless steel and solid zinc alloy.', '/samples/aae671_photo.png', 7, 1),
  (8, 'Door Viewers', 'door-viewers', 'ACCESSORIES', 'DOOR HARDWARE', 8, 'Wide-angle 180-degree optical brass door eye viewers with privacy covers and extension barrels for fire and entrance doors.', '/samples/aae825_photo.png', 8, 1)
INSERT INTO `finishes` (`id`, `name`, `slug`, `code`, `swatch_hex`, `swatch_gradient`, `description`, `sort_order`, `is_active`) VALUES
  (1, 'Satin SS', 'satin-ss', 'SSS', '#C4C6C8', 'linear-gradient(135deg, #D9DBDD 0%, #AEB1B5 50%, #CFD1D3 100%)', 'Brushed Satin Stainless Steel (SS304/SS316) offering superior corrosion resistance and a refined matte architectural sheen.', 1, 1),
  (2, 'Polished SS', 'polished-ss', 'PSS', '#E2E4E6', 'linear-gradient(135deg, #FFFFFF 0%, #C7CACD 45%, #F0F2F4 100%)', 'Mirror-polished Stainless Steel for crisp, bright contemporary architectural interiors.', 2, 1),
  (3, 'Ant. Brass', 'antique-brass', 'AB', '#8F7347', 'linear-gradient(135deg, #A98B5B 0%, #6D5430 55%, #8C7044 100%)', 'Warm hand-relieved Antique Brass finish bringing heritage character to classic and boutique spaces.', 3, 1),
  (4, 'Polish Brass', 'polished-brass', 'PB', '#D4AF37', 'linear-gradient(135deg, #F3D97E 0%, #C59B27 50%, #E7C85B 100%)', 'Lustrous mirror-finished Polished Brass engineered with protective lacquered or PVD coating.', 4, 1),
  (5, 'Satin Brass', 'satin-brass', 'SB', '#C8A951', 'linear-gradient(135deg, #DEC372 0%, #B3923C 55%, #D2B55E 100%)', 'Softly brushed Satin Brass delivering understated luxury and fingerprint-resistant warmth.', 5, 1),
  (6, 'Black Matt', 'black-matt', 'MB', '#1E1E1E', 'linear-gradient(135deg, #343434 0%, #141414 55%, #272727 100%)', 'Deep architectural Matt Black powder-coated / PVD finish for bold monochromatic contrast.', 6, 1),
  (7, 'Satin Nickel', 'satin-nickel', 'SN', '#B5B0A6', 'linear-gradient(135deg, #CFCAC0 0%, #9E988D 55%, #C0BBB1 100%)', 'Warm brushed Satin Nickel tone pairing seamlessly with neutral stone, oak, and bespoke joinery.', 7, 1),
  (8, 'Polish Chrome', 'polished-chrome', 'PC', '#D6DCE0', 'linear-gradient(135deg, #F7FAFC 0%, #B7C0C7 48%, #E5EBEF 100%)', 'High-gloss Polished Chrome plated over solid brass for timeless crisp reflectivity.', 8, 1)
